package versioncheck

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/entireclient/userdirs"
	"golang.org/x/mod/module"
	"golang.org/x/mod/semver"
)

const goosWindows = "windows"

// goos is a test seam for runtime.GOOS so the Windows-specific auto-install
// gating can be exercised from a non-Windows host.
var goos = runtime.GOOS

const (
	installManagerBrew    = "brew"
	installManagerMise    = "mise"
	installManagerScoop   = "scoop"
	installManagerUnknown = "unknown"
	installChannelStable  = "stable"
	installChannelNightly = "nightly"
)

// CheckAndNotify performs a version check and notifies the user if a newer version is available.
// This is the main entry point for the version check system.
// The function is silent on all errors to avoid interrupting CLI operations.
func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
	// Skip checks for local/unreleased builds.
	if isDevBuild(currentVersion) {
		return
	}

	// Ensure the global config directory exists
	if err := ensureGlobalConfigDir(); err != nil {
		// Silent failure - don't block CLI operations
		return
	}

	// Load the cache to check when we last fetched
	cache, err := loadCache()
	if err != nil {
		cache = &VersionCache{}
	}

	// Skip if we checked recently (within 24 hours)
	if time.Since(cache.LastCheckTime) < checkInterval {
		return
	}

	// Fetch the latest version from the appropriate channel
	var latestVersion string
	if isNightly(currentVersion) {
		latestVersion, err = fetchLatestNightlyVersion(ctx)
	} else {
		latestVersion, err = fetchLatestVersion(ctx)
	}

	// Always update cache to avoid retrying on every CLI invocation
	cache.LastCheckTime = time.Now()
	if saveErr := saveCache(cache); saveErr != nil {
		logging.Debug(ctx, "version check: failed to save cache",
			"error", saveErr.Error())
	}

	if err != nil {
		logging.Debug(ctx, "version check: failed to fetch latest version",
			"error", err.Error())
		return
	}

	// Show notification and offer an interactive upgrade when outdated
	if isOutdated(currentVersion, latestVersion) {
		if cache.SkippedVersion == versionCacheKey(latestVersion) {
			return
		}

		action := MaybeAutoUpdate(ctx, w, currentVersion, latestVersion)
		if action == autoUpdateActionSkipUntilNextVersion {
			cache.SkippedVersion = versionCacheKey(latestVersion)
			if saveErr := saveCache(cache); saveErr != nil {
				logging.Debug(ctx, "version check: failed to save skipped version",
					"error", saveErr.Error())
			}
		}
	}
}

// globalConfigDirPath returns the CLI's global config directory. Resolution
// lives in userdirs.Config — the single implementation shared by all
// config-dir consumers (contexts.json, the file token store, this cache).
func globalConfigDirPath() string {
	return userdirs.Config()
}

// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
func ensureGlobalConfigDir() error {
	//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
	if err := os.MkdirAll(globalConfigDirPath(), 0o755); err != nil {
		return fmt.Errorf("creating config directory: %w", err)
	}

	return nil
}

// cacheFilePath returns the full path to the version check cache file.
func cacheFilePath() string {
	return filepath.Join(globalConfigDirPath(), cacheFileName)
}

// loadCache loads the version check cache from disk.
// Returns an error if the file doesn't exist or is corrupted.
func loadCache() (*VersionCache, error) {
	data, err := os.ReadFile(cacheFilePath())
	if err != nil {
		return nil, fmt.Errorf("reading cache file: %w", err)
	}

	var cache VersionCache
	if err := json.Unmarshal(data, &cache); err != nil {
		return nil, fmt.Errorf("parsing cache: %w", err)
	}

	return &cache, nil
}

// saveCache saves the version check cache to disk.
// Uses atomic write semantics (write to temp file, then rename).
func saveCache(cache *VersionCache) error {
	filePath := cacheFilePath()

	// Marshal to JSON
	data, err := json.MarshalIndent(cache, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling cache: %w", err)
	}

	// Write to temp file first (atomic write)
	dir := filepath.Dir(filePath)
	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
	if err != nil {
		return fmt.Errorf("creating temp file: %w", err)
	}
	defer os.Remove(tmpFile.Name())

	if _, err := tmpFile.Write(data); err != nil {
		_ = tmpFile.Close() // cleanup on error path
		return fmt.Errorf("writing cache: %w", err)
	}

	if err := tmpFile.Close(); err != nil {
		return fmt.Errorf("closing temp file: %w", err)
	}

	// Rename temp file to final location

	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
		return fmt.Errorf("renaming cache file: %w", err)
	}

	return nil
}

// fetchLatestVersion fetches the latest stable version tag from the GitHub API.
func fetchLatestVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching release info: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	version, err := parseGitHubRelease(body)
	if err != nil {
		return "", fmt.Errorf("parsing release: %w", err)
	}
	return version, nil
}

// isNightly returns true if the version string is a nightly build.
func isNightly(version string) bool {
	if !strings.HasPrefix(version, "v") {
		version = "v" + version
	}
	return strings.Contains(semver.Prerelease(version), "nightly")
}

// fetchLatestNightlyVersion fetches the latest nightly version tag from the GitHub releases list.
func fetchLatestNightlyVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching releases: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	var releases []GitHubRelease
	if err := json.Unmarshal(body, &releases); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	for _, r := range releases {
		if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
			return r.TagName, nil
		}
	}

	return "", errors.New("no nightly release found")
}

// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
// Filters out prerelease versions.
func parseGitHubRelease(body []byte) (string, error) {
	var release GitHubRelease
	if err := json.Unmarshal(body, &release); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	if release.Prerelease {
		return "", errors.New("only prerelease versions available")
	}

	if release.TagName == "" {
		return "", errors.New("empty tag name")
	}

	return release.TagName, nil
}

// isOutdated compares current and latest versions using semantic versioning.
// Returns true if current < latest.
func isOutdated(current, latest string) bool {
	// Ensure versions have "v" prefix for semver package
	if !strings.HasPrefix(current, "v") {
		current = "v" + current
	}
	if !strings.HasPrefix(latest, "v") {
		latest = "v" + latest
	}

	// Local/unreleased builds shouldn't trigger update notifications.
	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
	if isDevBuild(current) {
		return false
	}

	// semver.Compare returns -1 if current < latest
	return semver.Compare(current, latest) < 0
}

// isDevBuild reports whether v identifies a local, unreleased build that
// should not be nagged to update. This covers the "dev" sentinel and empty
// string (an unstamped binary), a Go pseudo-version (built from a commit that
// isn't a tagged release), and any build carrying +metadata such as "+dirty".
// Released builds — stable tags, nightly tags, and `go install ...@<tag>` —
// have clean semver and return false.
func isDevBuild(v string) bool {
	if v == "" || v == "dev" {
		return true
	}
	if !strings.HasPrefix(v, "v") {
		v = "v" + v
	}
	return !semver.IsValid(v) || module.IsPseudoVersion(v) || semver.Build(v) != ""
}

func versionCacheKey(version string) string {
	if version == "" || strings.HasPrefix(version, "v") {
		return version
	}
	return "v" + version
}

func displayVersion(version string) string {
	return strings.TrimPrefix(version, "v")
}

func releaseNotesURL(version string) string {
	return downloadsURL + "/tag/" + versionCacheKey(version)
}

// executablePath is the function used to get the current executable path.
// It's a variable so tests can override it.
var executablePath = os.Executable

func releaseChannel(version string) string {
	if isNightly(version) {
		return installChannelNightly
	}
	return installChannelStable
}

// scoopAppName returns the Scoop app directory the running binary lives under
// — the path segment after `/scoop/apps/` (e.g. "cli" or "entire") — or ""
// when the binary is not a Scoop install. This is the durable signal for the
// pre-rename package: a binary running from the `cli` app dir must migrate to
// `entire` regardless of its version (the fix ships in a final `cli` release,
// so the migrating binary's version is already past the rename).
func scoopAppName() string {
	execPath, err := executablePath()
	if err != nil {
		return ""
	}
	realPath, err := filepath.EvalSymlinks(execPath)
	if err != nil {
		realPath = execPath
	}
	normalized := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")
	_, rest, ok := strings.Cut(normalized, "/scoop/apps/")
	if !ok {
		return ""
	}
	if app, _, ok := strings.Cut(rest, "/"); ok {
		return app
	}
	return rest
}

func installManagerForCurrentBinary() string {
	execPath, err := executablePath()
	if err != nil {
		return installManagerUnknown
	}

	realPath, err := filepath.EvalSymlinks(execPath)
	if err != nil {
		realPath = execPath
	}
	normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")

	switch {
	case strings.Contains(normalizedPath, "/Cellar/") ||
		strings.Contains(normalizedPath, "/opt/homebrew/") ||
		strings.Contains(normalizedPath, "/linuxbrew/") ||
		strings.Contains(normalizedPath, "/Caskroom/"):
		return installManagerBrew
	case strings.Contains(normalizedPath, "/mise/installs/"):
		return installManagerMise
	case strings.Contains(normalizedPath, "/scoop/apps/"):
		return installManagerScoop
	default:
		return installManagerUnknown
	}
}

// canAutoInstall reports whether updateCommand(currentVersion) is safe to
// execute on the current OS. Returns false on Windows when the install
// manager is unknown, because the POSIX curl-pipe-bash fallback can't run
// from cmd.exe and there's no Windows-native installer to substitute.
func canAutoInstall() bool {
	if goos != goosWindows {
		return true
	}
	switch installManagerForCurrentBinary() {
	case installManagerScoop, installManagerMise:
		return true
	default:
		return false
	}
}

// downloadsURL is the public page users visit when we can't offer an
// auto-installable command on their platform.
const downloadsURL = "https://github.com/entireio/cli/releases"

// updateCommand returns the appropriate update instruction based on how the binary was installed.
func updateCommand(currentVersion string) string {
	switch installManagerForCurrentBinary() {
	case installManagerBrew:
		if releaseChannel(currentVersion) == installChannelNightly {
			return "brew upgrade --yes entire@nightly"
		}
		return "brew upgrade --yes entire"
	case installManagerMise:
		return "mise upgrade entire"
	case installManagerScoop:
		// The Scoop package was renamed from `cli` to `entire`. A binary still
		// running from the old `cli` app dir can never cross the rename with a
		// plain `scoop update entire/cli`, so migrate it: install the new
		// `entire` package, remove the old `cli` package, then reset the shared
		// `entire.exe` shim (which uninstalling `cli` can take with it).
		//
		// These are three separate one-command lines, NOT a shell one-liner.
		// The string is both auto-run and printed for the user to paste into an
		// unknown shell (cmd, PowerShell, git-bash, WSL), so it must carry no
		// `;`/`&&`/conditional. realRunInstaller runs each line as its own
		// process and stops on the first failure, so the uninstall only runs
		// once the install has succeeded — a stale bucket or transient failure
		// never leaves the user without a working CLI. `scoop install` also
		// auto-refreshes the bucket when >3h stale (is_scoop_outdated), so the
		// new manifest lands without an explicit refresh. Binaries already on
		// the `entire` app just update in place.
		if scoopAppName() == "cli" {
			return "scoop install entire/entire\nscoop uninstall entire/cli\nscoop reset entire"
		}
		return "scoop update entire/entire"
	}

	if releaseChannel(currentVersion) == installChannelNightly {
		return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
	}
	return "curl -fsSL https://entire.io/install.sh | bash"
}

func UpdateCommandForCurrentBinary(currentVersion string) string {
	if !canAutoInstall() {
		return downloadsURL
	}
	return updateCommand(currentVersion)
}

// printNotification prints the version update notification to the user.
func printNotification(w io.Writer, current, latest string) {
	fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
		displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
}

package versioncheck

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"runtime"
	"strings"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/uiform"
)

// envKillSwitch disables the interactive update prompt regardless of TTY.
const envKillSwitch = "ENTIRE_NO_AUTO_UPDATE"

// AutoUpdateAction describes the result of an update prompt.
type AutoUpdateAction string

const (
	autoUpdateActionSkip                 AutoUpdateAction = "skip"
	autoUpdateActionUpdate               AutoUpdateAction = "update"
	autoUpdateActionSkipUntilNextVersion AutoUpdateAction = "skip_until_next_version"
)

// chooseUpdateFn is the signature for the update-prompt seam. The
// concrete implementation renders a huh.Select with the installer
// command interpolated into option 1.
type chooseUpdateFn func(ctx context.Context, currentVersion, latestVersion, cmdStr string) (AutoUpdateAction, error)

// Test seams.
var (
	runInstaller                 = realRunInstaller
	chooseUpdate  chooseUpdateFn = realChooseUpdate
	isTerminalOut                = interactive.IsTerminalWriter
)

// MaybeAutoUpdate prints an update notification and offers an interactive
// upgrade. Silent on every failure path — it must never interrupt the CLI.
//
// The same 3-option prompt (update / skip / skip until next version) is
// shown for every install manager that supports auto-installation
// (brew, mise, scoop, curl-bash). The only thing that varies between
// installers is the shell command interpolated into option 1.
//
// If the installer command fails, a hint with the exact command is
// printed so the user can retry manually. The 24h version-check cache
// is not invalidated on failure: we don't want to re-prompt on every
// invocation while an upstream issue (network, auth, repo outage) is
// still in place.
//
// When the prompt cannot be shown (kill switch set, or non-interactive
// environment like CI / agent subprocess / no TTY) the installer
// command is printed so the user still learns what to run manually.
//
// On Windows + unknown install manager the POSIX curl-pipe-bash fallback
// can't auto-run and there's no native equivalent, so we point the user
// at the releases download page instead.
func MaybeAutoUpdate(ctx context.Context, w io.Writer, currentVersion, latestVersion string) AutoUpdateAction {
	if !canAutoInstall() {
		printNotification(w, currentVersion, latestVersion)
		fmt.Fprintf(w, "To update, download the latest release from:\n  %s\n", downloadsURL)
		return autoUpdateActionSkip
	}

	cmdStr := updateCommand(currentVersion)

	if os.Getenv(envKillSwitch) != "" || !interactive.CanPromptInteractively() || !isTerminalOut(w) {
		printNotification(w, currentVersion, latestVersion)
		fmt.Fprintf(w, "To update, run:\n%s\n", indentCommand(cmdStr))
		return autoUpdateActionSkip
	}

	action, err := chooseUpdate(ctx, currentVersion, latestVersion, cmdStr)
	if err != nil {
		logging.Debug(ctx, "auto-update: prompt failed", "error", err.Error())
		return autoUpdateActionSkip
	}

	switch action {
	case autoUpdateActionUpdate:
		fmt.Fprintf(w, "\nUpdating Entire CLI:\n%s\n", indentCommand(cmdStr))
		if err := runInstaller(ctx, cmdStr); err != nil {
			fmt.Fprintf(w, "Update failed: %v\nTry again later running:\n%s\n", err, indentCommand(cmdStr))
			return autoUpdateActionUpdate
		}
		fmt.Fprintln(w, "Update complete. Re-run entire to use the new version.")
		return autoUpdateActionUpdate
	case autoUpdateActionSkipUntilNextVersion:
		return autoUpdateActionSkipUntilNextVersion
	case autoUpdateActionSkip:
		return autoUpdateActionSkip
	default:
		return autoUpdateActionSkip
	}
}

// realChooseUpdate renders a huh.Select with the three update actions.
// In normal mode this is an arrow-key TUI; when ACCESSIBLE is set huh
// falls back to a plain numbered prompt readable by screen readers.
func realChooseUpdate(ctx context.Context, currentVersion, latestVersion, cmdStr string) (AutoUpdateAction, error) {
	action := autoUpdateActionUpdate
	sel := huh.NewSelect[AutoUpdateAction]().
		Title(fmt.Sprintf("Update available! %s -> %s",
			displayVersion(currentVersion), displayVersion(latestVersion))).
		Description("Release notes: "+releaseNotesURL(latestVersion)).
		Options(
			huh.NewOption(fmt.Sprintf("Update now (runs `%s`)", cmdStr), autoUpdateActionUpdate),
			huh.NewOption("Skip", autoUpdateActionSkip),
			huh.NewOption("Skip until next version", autoUpdateActionSkipUntilNextVersion),
		).
		Value(&action)
	form := uiform.New(huh.NewGroup(sel))
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
			return autoUpdateActionSkip, nil
		}
		return autoUpdateActionSkip, fmt.Errorf("update prompt: %w", err)
	}
	return action, nil
}

// indentCommand indents each line of a (possibly multi-line) installer command
// so it reads as a block under a "run:" heading.
func indentCommand(cmdStr string) string {
	return "  " + strings.ReplaceAll(cmdStr, "\n", "\n  ")
}

// realRunInstaller shells out to the installer command, streaming stdin/stdout/stderr
// so password prompts and progress output reach the user.
//
// cmdStr may hold several newline-separated commands (e.g. the Scoop package
// rename: install, uninstall, reset). Each line is run as its own process and
// a failure stops the sequence, so a later step never runs after an earlier one
// failed (the uninstall must not run if the install did not succeed). Keeping
// the steps as separate lines — rather than a `;`/`&&` shell one-liner — lets
// the same string be pasted into any shell the user happens to be in.
func realRunInstaller(ctx context.Context, cmdStr string) error {
	for line := range strings.SplitSeq(cmdStr, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		var c *exec.Cmd
		if runtime.GOOS == goosWindows {
			c = exec.CommandContext(ctx, "cmd", "/C", line)
		} else {
			c = exec.CommandContext(ctx, "sh", "-c", line)
		}
		c.Stdin = os.Stdin
		c.Stdout = os.Stdout
		c.Stderr = os.Stderr
		if err := c.Run(); err != nil {
			return fmt.Errorf("installer exited: %w", err)
		}
	}
	return nil
}

